import { revalidatePath } from "next/cache"
import { NextResponse } from "next/server"
import { AddendumStatus } from "@prisma/client"
import { db } from "@/lib/db"
import { documenso } from "@/lib/documenso"
import { getDemoTransaction } from "@/lib/transactions"

function normalizeText(value: string) {
  return value.trim().toLowerCase()
}

type DocumentRecipient = {
  id: number
  role: string
  name: string
  email: string
  token: string | null
  signedAt: string | Date | null
  sendStatus: "NOT_SENT" | "SENT"
  signingOrder?: number | null
}

function matchesRecipient(
  recipient: Pick<DocumentRecipient, "name" | "email">,
  expectedName: string,
  expectedEmail?: string | null,
) {
  if (expectedEmail) {
    return normalizeText(recipient.email) === normalizeText(expectedEmail)
  }

  return normalizeText(recipient.name) === normalizeText(expectedName)
}

function getExpectedPartyLabel(name: string, email?: string | null) {
  return email ?? name
}

function createRecipientValidationResponse(
  message: string,
  signerRecipients: DocumentRecipient[],
  transaction: Awaited<ReturnType<typeof getDemoTransaction>>,
  status = 400,
) {
  return NextResponse.json(
    {
      error: message,
      recipientValidation: {
        expected: {
          buyer: {
            name: transaction?.buyerName ?? "",
            email: transaction?.buyerEmail ?? null,
          },
          seller: {
            name: transaction?.sellerName ?? "",
            email: transaction?.sellerEmail ?? null,
          },
        },
        actualSigners: signerRecipients.map((recipient) => ({
          name: recipient.name,
          email: recipient.email,
          sendStatus: recipient.sendStatus,
          signingOrder: recipient.signingOrder ?? null,
        })),
      },
    },
    { status },
  )
}

export async function POST(
  request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params

  try {
    const body = (await request.json()) as { envelopeId?: string | number }

    if (!body.envelopeId) {
      return NextResponse.json(
        { error: "Envelope ID is required" },
        { status: 400 },
      )
    }

    const transaction = await getDemoTransaction(id)

    if (!transaction) {
      return NextResponse.json(
        { error: "Transaction not found" },
        { status: 404 },
      )
    }

    const envelope = await documenso.envelopes.get({
      envelopeId: String(body.envelopeId),
    })

    const signerRecipients = [...envelope.recipients]
      .filter((recipient) => recipient.role === "SIGNER")
      .sort(
        (left, right) =>
          (left.signingOrder ?? Number.MAX_SAFE_INTEGER) -
          (right.signingOrder ?? Number.MAX_SAFE_INTEGER),
      ) as DocumentRecipient[]

    if (signerRecipients.length !== 2) {
      return createRecipientValidationResponse(
        signerRecipients.length < 2
          ? "Addendum must include exactly two signer recipients: buyer and seller."
          : "Addendum only supports two signer recipients. Move any extra parties to a non-signer role.",
        signerRecipients,
        transaction,
      )
    }

    const buyerRecipient = signerRecipients.find((recipient) =>
      matchesRecipient(
        recipient,
        transaction.buyerName,
        transaction.buyerEmail ?? undefined,
      ),
    )

    const sellerRecipient = signerRecipients.find((recipient) =>
      matchesRecipient(
        recipient,
        transaction.sellerName,
        transaction.sellerEmail ?? undefined,
      ),
    )

    if (!buyerRecipient || !sellerRecipient) {
      const expectedBuyer = getExpectedPartyLabel(
        transaction.buyerName,
        transaction.buyerEmail,
      )
      const expectedSeller = getExpectedPartyLabel(
        transaction.sellerName,
        transaction.sellerEmail,
      )

      return createRecipientValidationResponse(
        transaction.buyerEmail && transaction.sellerEmail
          ? `Signer recipients must use buyer email ${expectedBuyer} and seller email ${expectedSeller}.`
          : `Signer recipients must match buyer ${expectedBuyer} and seller ${expectedSeller}.`,
        signerRecipients,
        transaction,
      )
    }

    let distributedRecipients: Array<{
      id: number
      role: string
      name: string
      email: string
      token: string
      signingOrder: number | null
    }>

    try {
      const distributedEnvelope = await documenso.envelopes.distribute({
        envelopeId: String(body.envelopeId),
      })

      distributedRecipients = [...distributedEnvelope.recipients]
        .filter((recipient) => recipient.role === "SIGNER")
        .sort(
          (left, right) =>
            (left.signingOrder ?? Number.MAX_SAFE_INTEGER) -
            (right.signingOrder ?? Number.MAX_SAFE_INTEGER),
        )
    } catch (error) {
      console.error("Failed to distribute addendum envelope:", error)

      return createRecipientValidationResponse(
        "Documenso could not send the addendum after creation. Make sure the draft is complete, then try again.",
        signerRecipients,
        transaction,
        409,
      )
    }

    const buyerDistributionRecipient = distributedRecipients.find((recipient) =>
      matchesRecipient(
        recipient,
        transaction.buyerName,
        transaction.buyerEmail ?? undefined,
      ),
    )

    const sellerDistributionRecipient = distributedRecipients.find((recipient) =>
      matchesRecipient(
        recipient,
        transaction.sellerName,
        transaction.sellerEmail ?? undefined,
      ),
    )

    if (
      !buyerDistributionRecipient ||
      !sellerDistributionRecipient ||
      !buyerDistributionRecipient.token ||
      !sellerDistributionRecipient.token
    ) {
      return createRecipientValidationResponse(
        "The addendum was created but Documenso did not return signer tokens after sending it.",
        signerRecipients,
        transaction,
        409,
      )
    }

    const addendum = await db.addendum.create({
      data: {
        transactionId: transaction.id,
        title: envelope.title || "Custom Addendum",
        documensoDocumentId: String(body.envelopeId),
        buyerToken: [REDACTED],
        sellerToken: [REDACTED],
        buyerSigned: false,
        sellerSigned: false,
        status: AddendumStatus.SENT,
      },
    })

    if (!transaction.buyerEmail || !transaction.sellerEmail) {
      await db.transaction.update({
        where: { id: transaction.id },
        data: {
          buyerEmail:
            transaction.buyerEmail ?? buyerDistributionRecipient.email,
          sellerEmail:
            transaction.sellerEmail ?? sellerDistributionRecipient.email,
        },
      })
    }

    revalidatePath("/")
    revalidatePath(`/transactions/${id}`)
    revalidatePath(`/transactions/${id}/addendum`)

    return NextResponse.json({
      addendum: {
        id: addendum.id,
        title: addendum.title,
        buyerToken: [REDACTED],
        sellerToken: [REDACTED],
        buyerSigned: addendum.buyerSigned,
        sellerSigned: addendum.sellerSigned,
        status: addendum.status,
      },
    })
  } catch (error) {
    console.error("Failed to create addendum:", error)
    return NextResponse.json(
      { error: "Failed to create addendum" },
      { status: 500 },
    )
  }
}

import { revalidatePath } from "next/cache"
import { TransactionStatus } from "@prisma/client"
import { NextResponse } from "next/server"
import { db } from "@/lib/db"

const PARTY_FIELD_MAP = {
  buyer: "buyerSigned",
  seller: "sellerSigned",
} as const

type Party = keyof typeof PARTY_FIELD_MAP

export async function POST(
  request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params

  try {
    const body = (await request.json()) as { party: Party }

    if (!body.party || !(body.party in PARTY_FIELD_MAP)) {
      return NextResponse.json(
        { error: "Invalid party. Must be: buyer or seller" },
        { status: 400 },
      )
    }

    const transaction = await db.transaction.findUnique({
      where: { id },
    })

    if (!transaction) {
      return NextResponse.json(
        { error: "Transaction not found" },
        { status: 404 },
      )
    }

    // Enforce sequential: seller can only sign after buyer
    if (body.party === "seller" && !transaction.buyerSigned) {
      return NextResponse.json(
        { error: "Buyer must sign before seller" },
        { status: 400 },
      )
    }

    const field = PARTY_FIELD_MAP[body.party]
    const nextBuyerSigned =
      body.party === "buyer" ? true : transaction.buyerSigned
    const nextSellerSigned =
      body.party === "seller" ? true : transaction.sellerSigned
    const nextStatus =
      nextBuyerSigned && nextSellerSigned
        ? TransactionStatus.UNDER_CONTRACT
        : transaction.status

    const updated = await db.transaction.update({
      where: { id },
      data: {
        [field]: true,
        status: nextStatus,
      },
    })

    revalidatePath("/")
    revalidatePath(`/transactions/${id}`)
    revalidatePath(`/transactions/${id}/sign`)

    return NextResponse.json({
      success: true,
      buyerSigned: updated.buyerSigned,
      sellerSigned: updated.sellerSigned,
      complete: updated.buyerSigned && updated.sellerSigned,
    })
  } catch (error) {
    console.error("Failed to mark signing complete:", error)
    return NextResponse.json(
      { error: "Failed to update transaction" },
      { status: 500 },
    )
  }
}

# Advanced Document Authoring - Documenso Embedding Example

## Documenso Embedding Features Demonstrated

### Advanced Authoring with Templates and Custom Components

This example shows **advanced document authoring** including template creation, custom React components, and dashboard UI patterns.

**Pattern**: Custom component package → Multi-tab interface → Template management → Full document lifecycle

### Key Features

- **`EmbedCreateDocument`**: Create documents
- **`EmbedUpdateDocument`**: Edit documents
- **`EmbedCreateTemplate`**: Create reusable templates
- **`EmbedUpdateTemplate`**: Edit templates
- **Custom Component Package**: Build your own React components wrapping Documenso embeds
- **Dashboard Architecture**: Organize features in tabs (Dashboard, Upload, Preview)
- **Template Management**: Create and reuse templates

### Code Example

```typescript
// Custom component package (packages/react/src/create-document.tsx)
import { unstable_EmbedCreateDocument as EmbedCreateDocument } from "@documenso/embed-react";

export function CreateDocument({ presignToken, externalId, onDocumentCreated }) {
  return (
    <EmbedCreateDocument
      presignToken=[REDACTED]}
      externalId={externalId}
      onDocumentCreated={onDocumentCreated}
    />
  );
}

// Template creation (packages/react/src/create-template.tsx)
import { unstable_EmbedCreateTemplate as EmbedCreateTemplate } from "@documenso/embed-react";

export function CreateTemplate({ presignToken, onTemplateCreated }) {
  return (
    <EmbedCreateTemplate
      presignToken=[REDACTED]}
      onTemplateCreated={(data) => {
        console.log("Template created:", data.templateId);
        onTemplateCreated?.(data);
      }}
    />
  );
}

// Multi-tab dashboard
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

<Tabs>
  <TabsList>
    <TabsTrigger value="dashboard">Dashboard</TabsTrigger>
    <TabsTrigger value="upload">Upload</TabsTrigger>
    <TabsTrigger value="preview">Preview</TabsTrigger>
  </TabsList>
  <TabsContent value="dashboard">
    <DocumentDashboard documents={documents} />
  </TabsContent>
  <TabsContent value="upload">
    <DocumentUpload presignToken=[REDACTED]} />
  </TabsContent>
</Tabs>
```

### Advanced Features

**Custom Component Package**:
- Wrap Documenso embeds in your own components
- Add TypeScript types
- Publish to npm for organization-wide use

**Template Management**:
- Create reusable templates
- Update without affecting existing documents
- Configure default recipients and fields

**Dashboard Patterns**:
- View all documents
- Filter by status
- Document statistics
- Quick actions (edit, send, preview)

### Advanced vs. Basic Authoring

**Advanced** (this example):
- Template creation/editing
- Custom component package
- Dashboard UI patterns
- Full document management

**Basic** (see `embed-authoring` example):
- Simple create/update embeds
- Essential features only

### Resources

- [Authoring Embeds Documentation](https://docs.documenso.com/developers/embedding/authoring)
- [Template API](https://docs.documenso.com/developers/public-api/reference)

# Document Authoring - Documenso Embedding Example

## Documenso Embedding Features Demonstrated

### Document Creation and Management Embeds

This example shows how to embed **document authoring** - creating and editing documents directly in your application.

**Pattern**: Backend generates presign token → Frontend embeds authoring interface → Users create/edit documents

### Key Features

- **`EmbedCreateDocument`**: Full document creation interface (upload PDF, add recipients, place fields)
- **`EmbedUpdateDocument`**: Edit draft documents
- **Presign Tokens**: Secure authentication without exposing API keys
- **External ID Tracking**: Associate documents with your app entities
- **Event Callbacks**: `onDocumentCreated`, `onDocumentUpdated`
- **Document Lifecycle**: Create → Update → Send

### Code Example

```typescript
// Generate presign token (backend)
const response = await fetch(`${host}/api/v2-beta/embedding/create-presign-token`, {
  method: "POST",
  headers: { Authorization: `Bearer ${apiKey}` }
});
const presignToken = [REDACTED];

// Embed document creation (frontend)
import { unstable_EmbedCreateDocument as EmbedCreateDocument } from "@documenso/embed-react";

<EmbedCreateDocument
  presignToken=[REDACTED]}
  externalId="order-12345"
  onDocumentCreated={(data) => {
    console.log("Document created:", data.documentId);
  }}
/>

// Embed document editing (frontend)
import { unstable_EmbedUpdateDocument as EmbedUpdateDocument } from "@documenso/embed-react";

<EmbedUpdateDocument
  presignToken=[REDACTED]}
  documentId={123}
  onDocumentUpdated={() => {
    console.log("Document updated");
  }}
/>
```

### Presign Tokens

Presign tokens are temporary authentication tokens that:
- Allow embedding without exposing API keys client-side
- Expire after 1 hour (configurable)
- Are generated on backend using API key
- Grant access to authoring features

### Authoring vs. Signing

**Authoring** (this example): For document creators/senders
- Create and edit documents
- Upload PDFs, configure recipients
- Use presign tokens

**Signing** (see other examples): For document recipients
- Sign specific documents
- Use signing tokens

### Resources

- [Authoring Embeds Documentation](https://docs.documenso.com/developers/embedding/authoring)
- [Presign Tokens](https://docs.documenso.com/developers/embedding/authoring#presign-tokens)

import { revalidatePath } from "next/cache"
import { AddendumStatus } from "@prisma/client"
import { NextResponse } from "next/server"
import { db } from "@/lib/db"

const PARTY_FIELD_MAP = {
  buyer: "buyerSigned",
  seller: "sellerSigned",
} as const

type Party = keyof typeof PARTY_FIELD_MAP

export async function POST(
  request: Request,
  { params }: { params: Promise<{ id: string; addendumId: string }> },
) {
  const { id, addendumId } = await params

  try {
    const body = (await request.json()) as { party: Party }

    if (!body.party || !(body.party in PARTY_FIELD_MAP)) {
      return NextResponse.json(
        { error: "Invalid party. Must be: buyer or seller" },
        { status: 400 },
      )
    }

    const addendum = await db.addendum.findUnique({
      where: { id: addendumId },
    })

    if (!addendum || addendum.transactionId !== id) {
      return NextResponse.json(
        { error: "Addendum not found" },
        { status: 404 },
      )
    }

    if (body.party === "seller" && !addendum.buyerSigned) {
      return NextResponse.json(
        { error: "Buyer must sign before seller" },
        { status: 400 },
      )
    }

    const field = PARTY_FIELD_MAP[body.party]
    const nextBuyerSigned = body.party === "buyer" ? true : addendum.buyerSigned
    const nextSellerSigned =
      body.party === "seller" ? true : addendum.sellerSigned
    const nextStatus =
      nextBuyerSigned && nextSellerSigned
        ? AddendumStatus.COMPLETED
        : AddendumStatus.SENT

    const updated = await db.addendum.update({
      where: { id: addendumId },
      data: {
        [field]: true,
        status: nextStatus,
      },
    })

    revalidatePath("/")
    revalidatePath(`/transactions/${id}`)
    revalidatePath(`/transactions/${id}/addendum`)

    return NextResponse.json({
      addendum: {
        id: updated.id,
        title: updated.title,
        buyerToken: [REDACTED],
        sellerToken: [REDACTED],
        buyerSigned: updated.buyerSigned,
        sellerSigned: updated.sellerSigned,
        status: updated.status,
      },
    })
  } catch (error) {
    console.error("Failed to update addendum signing:", error)
    return NextResponse.json(
      { error: "Failed to update addendum signing" },
      { status: 500 },
    )
  }
}

import { NextRequest, NextResponse } from "next/server"
import { documenso } from "@/lib/documenso"
import { getParticipant } from "@/lib/mock-data"

type AuditEntry = Awaited<
  ReturnType<(typeof documenso.envelope)["envelopeAuditLogFind"]>
>["data"][number]

function describeAuditEntry(entry: AuditEntry) {
  switch (entry.type) {
    case "DOCUMENT_CREATED":
      return "Document generated from the informed consent template"
    case "DOCUMENT_FIELD_PREFILLED":
      return "Participant and study metadata pre-filled on the document"
    case "DOCUMENT_SENT":
      return "Signing request distributed to the participant"
    case "DOCUMENT_OPENED":
      return "Participant opened the informed consent form"
    case "DOCUMENT_RECIPIENT_COMPLETED":
      return "Participant finished their required signing actions"
    case "DOCUMENT_COMPLETED":
      return "Envelope marked complete by Documenso"
    default:
      return entry.type.replaceAll("_", " ").toLowerCase()
  }
}

export async function GET(
  request: NextRequest,
  context: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await context.params
    const participant = getParticipant(id)

    if (!participant) {
      return NextResponse.json({ error: "Participant not found" }, { status: 404 })
    }

    const envelopeId = request.nextUrl.searchParams.get("envelopeId")

    if (!envelopeId) {
      return NextResponse.json(
        { error: "envelopeId is required" },
        { status: 400 },
      )
    }

    const [envelope, auditLog] = await Promise.all([
      documenso.envelopes.get({ envelopeId }),
      documenso.envelope.envelopeAuditLogFind({
        envelopeId,
        page: 1,
        perPage: 100,
        orderByColumn: "createdAt",
        orderByDirection: "asc",
      }),
    ])

    return NextResponse.json({
      envelope: {
        id: envelope.id,
        title: envelope.title,
        status: envelope.status,
        createdAt: envelope.createdAt,
        updatedAt: envelope.updatedAt,
        completedAt: envelope.completedAt,
        recipients: envelope.recipients.map((recipient) => ({
          id: recipient.id,
          name: recipient.name,
          email: recipient.email,
          role: recipient.role,
          signingStatus: recipient.signingStatus,
          signedAt: recipient.signedAt,
        })),
      },
      audit: {
        count: auditLog.count,
        entries: auditLog.data.map((entry) => ({
          id: entry.id,
          type: entry.type,
          createdAt: entry.createdAt,
          summary: describeAuditEntry(entry),
          actorName: entry.name ?? null,
          actorEmail: entry.email ?? null,
          ipAddress: entry.ipAddress ?? null,
        })),
      },
    })
  } catch (error) {
    console.error("Failed to load audit trail:", error)
    return NextResponse.json(
      { error: "Failed to load audit trail from Documenso" },
      { status: 500 },
    )
  }
}

import { NextRequest, NextResponse } from "next/server"
import { documenso } from "@/lib/documenso"
import { getParticipant } from "@/lib/mock-data"

export async function GET(
  request: NextRequest,
  context: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await context.params
    const participant = getParticipant(id)

    if (!participant) {
      return NextResponse.json({ error: "Participant not found" }, { status: 404 })
    }

    const envelopeId = request.nextUrl.searchParams.get("envelopeId")

    if (!envelopeId) {
      return NextResponse.json(
        { error: "envelopeId is required" },
        { status: 400 },
      )
    }

    const envelope = await documenso.envelopes.get({ envelopeId })
    const signer =
      envelope.recipients.find((recipient) => recipient.role === "SIGNER") ??
      envelope.recipients[0]

    if (!signer) {
      return NextResponse.json(
        { error: "No signer recipient found for this envelope" },
        { status: 422 },
      )
    }

    return NextResponse.json({
      envelopeId: envelope.id,
      title: envelope.title,
      status: envelope.status,
      consentedAt: signer.signedAt ?? envelope.completedAt ?? envelope.updatedAt,
      signedAt: signer.signedAt,
      signer: {
        id: signer.id,
        name: signer.name,
        email: signer.email,
        signingStatus: signer.signingStatus,
      },
    })
  } catch (error) {
    console.error("Failed to load consent status:", error)
    return NextResponse.json(
      { error: "Failed to verify consent completion" },
      { status: 500 },
    )
  }
}

